const TAG_COLORS = {
  SEO:           { bg: '#e8f5e9', color: '#2e7d32' },
  Promotions:    { bg: '#fff8e1', color: '#e65100' },
  Catalog:       { bg: '#f3e5f5', color: '#6a1b9a' },
  Communication: { bg: '#e3f2fd', color: '#1565c0' },
  Security:      { bg: '#fce4ec', color: '#c62828' },
  UX:            { bg: '#f0f0ff', color: '#6c63ff' },
  'Admin UX':    { bg: '#e0f7fa', color: '#00695c' },
  Data:          { bg: '#fff3e0', color: '#e65100' },
};

function CodeBlock({ code }) {
  return (
    <pre style={{ background: '#1e1e2e', color: '#cdd6f4', padding: '12px 16px', borderRadius: 10, fontSize: 12, fontFamily: 'monospace', overflowX: 'auto', margin: '8px 0 0', lineHeight: 1.6 }}>
      {code}
    </pre>
  );
}

function BeforeAfterCard({ side, data, accent }) {
  return (
    <div style={{ flex: 1, minWidth: 0, background: side === 'before' ? '#fff8f8' : '#f8fff8', border: `1.5px solid ${side === 'before' ? '#ffcccc' : '#b2dfdb'}`, borderRadius: 14, padding: 18 }}>
      <div style={{ fontWeight: 700, fontSize: 13, color: side === 'before' ? '#c62828' : '#00695c', marginBottom: 8, display: 'flex', alignItems: 'center', gap: 6 }}>
        {side === 'before' ? '✕ Before' : '✓ After'}
        <span style={{ fontWeight: 400, color: '#9e9e9e', fontSize: 12 }}>— {data.label}</span>
      </div>
      <CodeBlock code={data.code} />
      <ul style={{ margin: '10px 0 0', paddingLeft: 18 }}>
        {data.points.map((pt, i) => (
          <li key={i} style={{ fontSize: 13, color: '#424242', marginBottom: 4, lineHeight: 1.5 }}>{pt}</li>
        ))}
      </ul>
    </div>
  );
}

export default function WhatsNew() {
  const [expanded, setExpanded] = useState(null);
  const [filterTag, setFilterTag] = useState('');

  const tags = [...new Set(FEATURES.map(f => f.tag))];
  const visible = filterTag ? FEATURES.filter(f => f.tag === filterTag) : FEATURES;

  return (
    <AdminLayout>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', flexWrap: 'wrap', gap: 12, marginBottom: 28 }}>
        <div>
          <h1 style={{ fontSize: 26, fontWeight: 800, marginBottom: 4 }}>
            ✨ <span className="gradient-text">What's New</span>
          </h1>
          <p style={{ color: '#9e9e9e', fontSize: 14 }}>All features added to this admin panel — with before/after comparisons.</p>
        </div>
        <div style={{ background: '#f0f0ff', borderRadius: 12, padding: '8px 20px', fontSize: 14, fontWeight: 700, color: '#6c63ff' }}>
          {FEATURES.length} features
        </div>
      </div>

      {/* Tag filter */}
      <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', marginBottom: 24 }}>
        <button onClick={() => setFilterTag('')}
          style={{ padding: '5px 16px', borderRadius: 20, border: `2px solid ${!filterTag ? '#6c63ff' : '#e0e0e0'}`, background: !filterTag ? '#f0f0ff' : 'white', color: !filterTag ? '#6c63ff' : '#9e9e9e', fontSize: 13, fontWeight: 600, cursor: 'pointer' }}>
          All
        </button>
        {tags.map(tag => {
          const tc = TAG_COLORS[tag] || {};
          const active = filterTag === tag;
          return (
            <button key={tag} onClick={() => setFilterTag(tag)}
              style={{ padding: '5px 16px', borderRadius: 20, border: `2px solid ${active ? tc.color : '#e0e0e0'}`, background: active ? tc.bg : 'white', color: active ? tc.color : '#9e9e9e', fontSize: 13, fontWeight: 600, cursor: 'pointer' }}>
              {tag}
            </button>
          );
        })}
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
        {visible.map(feat => {
          const tc = TAG_COLORS[feat.tag] || { bg: '#f0f0ff', color: '#6c63ff' };
          const open = expanded === feat.id;
          return (
            <div key={feat.id} style={{ background: 'white', borderRadius: 18, border: `1.5px solid ${open ? '#6c63ff44' : '#f0f0f0'}`, boxShadow: open ? '0 4px 24px rgba(108,99,255,0.10)' : '0 2px 8px rgba(0,0,0,0.04)', transition: 'all 0.2s', overflow: 'hidden' }}>
              {/* Header row */}
              <div
                onClick={() => setExpanded(open ? null : feat.id)}
                style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '18px 24px', cursor: 'pointer', userSelect: 'none' }}>
                <span style={{ fontSize: 28, flexShrink: 0 }}>{feat.icon}</span>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                    <span style={{ fontWeight: 700, fontSize: 16 }}>{feat.title}</span>
                    <span style={{ padding: '2px 10px', borderRadius: 12, fontSize: 11, fontWeight: 700, background: tc.bg, color: tc.color }}>{feat.tag}</span>
                    <span style={{ fontSize: 12, color: '#bdbdbd' }}>{feat.date}</span>
                  </div>
                  <div style={{ fontSize: 13, color: '#636e72', marginTop: 3 }}>{feat.summary}</div>
                </div>
                <span style={{ fontSize: 18, color: '#9e9e9e', transition: 'transform 0.2s', transform: open ? 'rotate(180deg)' : 'rotate(0deg)', flexShrink: 0 }}>▾</span>
              </div>

              {/* Before / After body */}
              {open && (
                <div style={{ padding: '0 24px 24px', borderTop: '1px solid #f5f5f5' }}>
                  <div style={{ paddingTop: 18, display: 'flex', gap: 14, flexWrap: 'wrap' }}>
                    <BeforeAfterCard side="before" data={feat.before} />
                    <BeforeAfterCard side="after" data={feat.after} />
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </AdminLayout>
  );
}
